#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll x, y, c;
} Point;

typedef struct {
    ll v;
    int id;
} Coord;

typedef struct {
    ll num, den;
} Fraction;

static int cmp_coord(const void *a, const void *b) {
    const Coord *p = (const Coord *)a;
    const Coord *q = (const Coord *)b;
    if (p->v < q->v) return -1;
    if (p->v > q->v) return 1;
    return 0;
}

static ll gcdll(ll a, ll b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static int better(Fraction a, Fraction b) {
    /* return 1 if a > b */
    __int128 left = (__int128)a.num * b.den;
    __int128 right = (__int128)b.num * a.den;
    return left > right;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point *p = (Point *)malloc((size_t)n * sizeof(Point));
    Coord *xs = (Coord *)malloc((size_t)n * sizeof(Coord));
    Coord *ys = (Coord *)malloc((size_t)n * sizeof(Coord));

    for (int i = 0; i < n; ++i) {
        scanf("%lld %lld %lld", &p[i].x, &p[i].y, &p[i].c);
        xs[i].v = p[i].x; xs[i].id = i;
        ys[i].v = p[i].y; ys[i].id = i;
    }

    qsort(xs, n, sizeof(Coord), cmp_coord);
    qsort(ys, n, sizeof(Coord), cmp_coord);

    int *xr = (int *)malloc((size_t)n * sizeof(int));
    int *yr = (int *)malloc((size_t)n * sizeof(int));

    int xn = 0, yn = 0;
    for (int i = 0; i < n; ++i) {
        if (i == 0 || xs[i].v != xs[i - 1].v) xn++;
        xr[xs[i].id] = xn - 1;
    }
    for (int i = 0; i < n; ++i) {
        if (i == 0 || ys[i].v != ys[i - 1].v) yn++;
        yr[ys[i].id] = yn - 1;
    }

    ll *xval = (ll *)malloc((size_t)xn * sizeof(ll));
    ll *yval = (ll *)malloc((size_t)yn * sizeof(ll));
    for (int i = 0, j = 0; i < n; ++i) {
        if (i == 0 || xs[i].v != xs[i - 1].v) xval[j++] = xs[i].v;
    }
    for (int i = 0, j = 0; i < n; ++i) {
        if (i == 0 || ys[i].v != ys[i - 1].v) yval[j++] = ys[i].v;
    }

    ll *grid = (ll *)calloc((size_t)xn * yn, sizeof(ll));
    for (int i = 0; i < n; ++i) {
        int xi = xr[i], yi = yr[i];
        grid[(size_t)xi * yn + yi] += p[i].c;
    }

    ll *pref = (ll *)calloc((size_t)(xn + 1) * (yn + 1), sizeof(ll));
    for (int i = 0; i < xn; ++i) {
        for (int j = 0; j < yn; ++j) {
            pref[(size_t)(i + 1) * (yn + 1) + (j + 1)] =
                grid[(size_t)i * yn + j]
                + pref[(size_t)i * (yn + 1) + (j + 1)]
                + pref[(size_t)(i + 1) * (yn + 1) + j]
                - pref[(size_t)i * (yn + 1) + j];
        }
    }

    Fraction best = {0, 1};

    for (int x1 = 0; x1 < xn; ++x1) {
        for (int x2 = x1 + 1; x2 < xn; ++x2) {
            ll width = xval[x2] - xval[x1];
            for (int y1 = 0; y1 < yn; ++y1) {
                for (int y2 = y1 + 1; y2 < yn; ++y2) {
                    ll height = yval[y2] - yval[y1];
                    ll sum =
                        pref[(size_t)(x2 + 1) * (yn + 1) + (y2 + 1)]
                        - pref[(size_t)x1 * (yn + 1) + (y2 + 1)]
                        - pref[(size_t)(x2 + 1) * (yn + 1) + y1]
                        + pref[(size_t)x1 * (yn + 1) + y1];

                    Fraction cur = {sum, width * height};
                    if (better(cur, best)) best = cur;
                }
            }
        }
    }

    ll g = gcdll(best.num, best.den);
    best.num /= g;
    best.den /= g;

    printf("%lld/%lld\n", best.num, best.den);

    free(p);
    free(xs);
    free(ys);
    free(xr);
    free(yr);
    free(xval);
    free(yval);
    free(grid);
    free(pref);
    return 0;
}

