public class FoxObservation {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        // Store lairs grouped by x coordinate
        Map<Integer, List<int[]>> map = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);
            int c = Integer.parseInt(parts[2]);
            map.computeIfAbsent(x, k -> new ArrayList<>()).add(new int[]{y, c});
        }

        // Sort points within each x coordinate by y
        for (List<int[]> list : map.values()) {
            list.sort(Comparator.comparingInt(a -> a[0]));
        }

        long maxNum = 0;
        long maxDen = 1;

        List<Integer> xs = new ArrayList<>(map.keySet());
        Collections.sort(xs);
        int m = xs.size();

        // Try all pairs of distinct x coordinates
        for (int i = 0; i < m; i++) {
            int x1 = xs.get(i);
            List<int[]> list1 = map.get(x1);

            for (int j = i + 1; j < m; j++) {
                int x2 = xs.get(j);
                List<int[]> list2 = map.get(x2);

                long width = Math.abs((long)x1 - x2);

                // Two-pointer sweep over y
                int p1 = 0, p2 = 0;
                long sum1 = 0, sum2 = 0;

                while (p1 < list1.size() || p2 < list2.size()) {
                    int y;
                    if (p2 == list2.size() || (p1 < list1.size() && list1.get(p1)[0] <= list2.get(p2)[0])) {
                        y = list1.get(p1)[0];
                        while (p1 < list1.size() && list1.get(p1)[0] == y) {
                            sum1 += list1.get(p1)[1];
                            p1++;
                        }
                    } else {
                        y = list2.get(p2)[0];
                        while (p2 < list2.size() && list2.get(p2)[0] == y) {
                            sum2 += list2.get(p2)[1];
                            p2++;
                        }
                    }

                    long total = sum1 + sum2;
                    if (total > 0) {
                        // We consider rectangle from first y-coordinate seen to current y
                        // Actually we need to consider all pairs of y's, but we can do it while sweeping:
                        // The maximum will always occur at a y where sum1 or sum2 changes.
                        // We keep track of best seen so far.
                    }
                }

                // Brute force over all y pairs from the two lists (since n is small)
                long bestSum = 0;
                for (int a = 0; a < list1.size(); a++) {
                    long s1 = 0;
                    for (int b = a; b < list1.size(); b++) {
                        s1 += list1.get(b)[1];
                        long s2 = 0;
                        int yLow = list1.get(a)[0];
                        int yHigh = list1.get(b)[0];

                        // Add all points from list2 within y range [yLow, yHigh]
                        // Since lists are sorted, we can accumulate efficiently
                        // But for simplicity and correctness, just accumulate on the fly
                        // Use prefix sums
                    }
                }

                // More efficient: precompute prefix sums for each list
                long[] pref1 = new long[list1.size() + 1];
                for (int k = 0; k < list1.size(); k++) {
                    pref1[k+1] = pref1[k] + list1.get(k)[1];
                }
                long[] pref2 = new long[list2.size() + 1];
                for (int k = 0; k < list2.size(); k++) {
                    pref2[k+1] = pref2[k] + list2.get(k)[1];
                }

                for (int a = 0; a < list1.size(); a++) {
                    for (int b = a; b < list1.size(); b++) {
                        long sumY1 = pref1[b+1] - pref1[a];
                        int yLow = list1.get(a)[0];
                        int yHigh = list1.get(b)[0];

                        // Binary search indices in list2
                        int left = lowerBound(list2, yLow);
                        int right = upperBound(list2, yHigh) - 1;
                        long sumY2 = 0;
                        if (left <= right) {
                            sumY2 = pref2[right+1] - pref2[left];
                        }

                        long total = sumY1 + sumY2;
                        if (total > 0) {
                            long height = (long)yHigh - yLow;
                            if (height > 0) {
                                // Compare total / (width * height)
                                long num = total;
                                long den = width * height;
                                if (num * maxDen > maxNum * den) {
                                    maxNum = num;
                                    maxDen = den;
                                }
                            }
                        }
                    }
                }

                // Also consider rectangles where both y's come from list2
                for (int a = 0; a < list2.size(); a++) {
                    for (int b = a; b < list2.size(); b++) {
                        long sumY2 = pref2[b+1] - pref2[a];
                        int yLow = list2.get(a)[0];
                        int yHigh = list2.get(b)[0];

                        int left = lowerBound(list1, yLow);
                        int right = upperBound(list1, yHigh) - 1;
                        long sumY1 = 0;
                        if (left <= right) {
                            sumY1 = pref1[right+1] - pref1[left];
                        }

                        long total = sumY1 + sumY2;
                        if (total > 0) {
                            long height = (long)yHigh - yLow;
                            if (height > 0) {
                                long num = total;
                                long den = width * height;
                                if (num * maxDen > maxNum * den) {
                                    maxNum = num;
                                    maxDen = den;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Simplify fraction
        long g = gcd(maxNum, maxDen);
        maxNum /= g;
        maxDen /= g;
        System.out.println(maxNum + "/" + maxDen);
    }

    static int lowerBound(List<int[]> list, int key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid)[0] >= key) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    static int upperBound(List<int[]> list, int key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid)[0] > key) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

