import java.io.*;
import java.util.*;

/*
We are given N lattice points (xi, yi) with fox counts ci.
Choose two lattice points (x1, y1), (x2, y2) with x1 != x2 and y1 != y2.
They define an axis-aligned rectangle. Let N' be the total foxes in/on that rectangle.
Maximize:
    N' / (|x1-x2| * |y1-y2|)
Output the maximum as a reduced fraction.

Approach:
- Coordinate-compress x and y.
- Build 2D prefix sums of counts on compressed grid.
- For every pair of distinct x-columns (L, R):
    For each y-row i, compute rowSum[i] = total foxes with x in [L, R] and exact compressed y=i.
    We need maximize over a<b:
        (sum rowSum[a..b]) / ((x[R]-x[L]) * (y[b]-y[a]))
    For fixed x-width W, maximize:
        (prefix[b] - prefix[a-1]) / (y[b]-y[a])

  Rewrite using points:
    For bottom row a, define point P_a = (y[a], prefix[a-1])
    For top row b, objective is:
        (prefix[b] - prefix[a-1]) / (y[b]-y[a])
      = slope between P_a and Q_b where Q_b=(y[b], prefix[b])

  For each b in increasing y, we need the minimum possible denominator? Actually maximum slope from some previous P_a to current Q_b.
  Since x's increase and prefix values are monotone nondecreasing, we can maintain upper convex hull of candidate P_a points and query maximum slope to Q_b.
  Because query x increases, pointer walk works.

Complexities:
- Let X=#distinct x, Y=#distinct y, both <= N.
- 2D prefix: O(XY)
- Enumerate x-pairs: O(X^2 * Y)

This is fine for moderate N typical for such tasks.

Fraction comparison:
- Compare A/B and C/D by cross multiplication using BigInteger-safe? Counts and coordinates may be large.
- Use long; if products may overflow, use BigInteger for final comparisons.
To be safe, use BigInteger in comparisons of candidate fractions and slopes inside hull.
Given O(X^2 Y), BigInteger there would be too slow.
So use long arithmetic assuming input fits typical contest bounds. For final answer reduction use BigInteger gcd? long gcd is enough.

Geometry helpers use cross-multiplication with long.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) { this.x = x; this.y = y; }
    }

    // Compare slope(a->q1) <= slope(a->q2), assuming q1.x < q2.x and denominators positive
    static boolean slopeLE(Point a, Point q1, Point q2) {
        return (q1.y - a.y) * (q2.x - a.x) <= (q2.y - a.y) * (q1.x - a.x);
    }

    // For hull query: is slope(p1->q) <= slope(p2->q)?
    static boolean betterOrEqual(Point p1, Point p2, Point q) {
        return (q.y - p1.y) * (q.x - p2.x) <= (q.y - p2.y) * (q.x - p1.x);
    }

    // For maintaining upper hull of candidate points p1, p2, p3 with increasing x.
    // Remove p2 if it is unnecessary.
    static boolean bad(Point p1, Point p2, Point p3) {
        return (p2.y - p1.y) * (p3.x - p2.x) <= (p3.y - p2.y) * (p2.x - p1.x);
    }

    static long gcd(long a, long b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[] xs0 = new long[n];
        long[] ys0 = new long[n];
        long[] cs0 = new long[n];
        long[] allX = new long[n];
        long[] allY = new long[n];

        for (int i = 0; i < n; i++) {
            xs0[i] = fs.nextLong();
            ys0[i] = fs.nextLong();
            cs0[i] = fs.nextLong();
            allX[i] = xs0[i];
            allY[i] = ys0[i];
        }

        Arrays.sort(allX);
        Arrays.sort(allY);
        int X = uniqueInPlace(allX);
        int Y = uniqueInPlace(allY);

        long[] xs = Arrays.copyOf(allX, X);
        long[] ys = Arrays.copyOf(allY, Y);

        long[][] grid = new long[X + 1][Y + 1];
        for (int i = 0; i < n; i++) {
            int xi = Arrays.binarySearch(xs, xs0[i]) + 1;
            int yi = Arrays.binarySearch(ys, ys0[i]) + 1;
            grid[xi][yi] += cs0[i];
        }

        long[][] pref = new long[X + 1][Y + 1];
        for (int i = 1; i <= X; i++) {
            for (int j = 1; j <= Y; j++) {
                pref[i][j] = grid[i][j] + pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1];
            }
        }

        long bestNum = 0;
        long bestDen = 1;

        if (X >= 2 && Y >= 2) {
            long[] row = new long[Y + 1];
            long[] p = new long[Y + 1];

            for (int l = 1; l <= X; l++) {
                for (int r = l + 1; r <= X; r++) {
                    long width = xs[r - 1] - xs[l - 1];
                    if (width == 0) continue;

                    for (int y = 1; y <= Y; y++) {
                        row[y] = pref[r][y] - pref[l - 1][y] - pref[r][y - 1] + pref[l - 1][y - 1];
                    }

                    p[0] = 0;
                    for (int y = 1; y <= Y; y++) p[y] = p[y - 1] + row[y];

                    ArrayList<Point> hull = new ArrayList<>();
                    int ptr = 0;

                    // first candidate bottom = 1 corresponds to point (ys[0], p[0])
                    hull.add(new Point(ys[0], p[0]));

                    for (int b = 2; b <= Y; b++) {
                        Point q = new Point(ys[b - 1], p[b]);

                        while (ptr + 1 < hull.size() && betterOrEqual(hull.get(ptr), hull.get(ptr + 1), q)) {
                            ptr++;
                        }

                        Point bestP = hull.get(ptr);
                        long num = p[b] - bestP.y;
                        long den = width * (q.x - bestP.x);

                        if (num * bestDen > bestNum * den) {
                            bestNum = num;
                            bestDen = den;
                        }

                        // add candidate for a = b: point (ys[b-1], p[b-1])
                        Point np = new Point(ys[b - 1], p[b - 1]);
                        while (hull.size() >= 2 && bad(hull.get(hull.size() - 2), hull.get(hull.size() - 1), np)) {
                            hull.remove(hull.size() - 1);
                            if (ptr > hull.size() - 1) ptr = hull.size() - 1;
                        }
                        hull.add(np);
                    }
                }
            }
        }

        long g = gcd(bestNum, bestDen);
        System.out.println((bestNum / g) + "/" + (bestDen / g));
    }

    static int uniqueInPlace(long[] a) {
        if (a.length == 0) return 0;
        int m = 1;
        for (int i = 1; i < a.length; i++) {
            if (a[i] != a[m - 1]) a[m++] = a[i];
        }
        return m;
    }
}

