#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Frac {
    ll num, den;
    Frac(ll n = 0, ll d = 1) {
        if (d < 0) { n = -n; d = -d; }
        ll g = gcd(abs(n), abs(d));
        num = n / g;
        den = d / g;
    }
    bool operator<(const Frac& o) const {
        return num * o.den < o.num * den;
    }
    bool operator==(const Frac& o) const {
        return num == o.num && den == o.den;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<tuple<int,int,ll>> lairs(n);
    set<int> xs, ys;
    for (int i = 0; i < n; i++) {
        int x, y; ll c;
        cin >> x >> y >> c;
        lairs[i] = {x, y, c};
        xs.insert(x);
        ys.insert(y);
    }

    // coordinate compression
    vector<int> xlist(xs.begin(), xs.end());
    vector<int> ylist(ys.begin(), ys.end());
    int X = xlist.size(), Y = ylist.size();
    unordered_map<int,int> xid, yid;
    for (int i = 0; i < X; i++) xid[xlist[i]] = i;
    for (int i = 0; i < Y; i++) yid[ylist[i]] = i;

    // grid with sums
    vector<vector<ll>> grid(X, vector<ll>(Y, 0));
    for (auto& [x,y,c] : lairs) {
        grid[xid[x]][yid[y]] += c;
    }

    // 2D prefix sums
    vector<vector<ll>> pref(X+1, vector<ll>(Y+1, 0));
    for (int i = 0; i < X; i++) {
        for (int j = 0; j < Y; j++) {
            pref[i+1][j+1] = grid[i][j] + pref[i][j+1] + pref[i+1][j] - pref[i][j];
        }
    }

    auto sum = [&](int x1, int y1, int x2, int y2) -> ll {
        // inclusive of both corners
        return pref[x2+1][y2+1] - pref[x1][y2+1] - pref[x2+1][y1] + pref[x1][y1];
    };

    Frac best(0,1);

    // Fix left and right x coordinates
    for (int lx = 0; lx < X; lx++) {
        for (int rx = lx+1; rx < X; rx++) {
            ll dx = abs(xlist[rx] - xlist[lx]);
            // For each pair of y coordinates, compute sum in rectangle
            // We need to find max over y1<y2 of sum(lx,y1,rx,y2) / (dx * |y1-y2|)
            // Equivalent to maximize sum / (dx * dy) = (sum/dx) / dy
            // For fixed dx, we need max over y intervals of (sum / dy)
            // We can treat each y slice between lx and rx as a value array
            // Build array of sums per y: total between lx and rx for each y
            vector<ll> col(Y, 0);
            for (int y = 0; y < Y; y++) {
                col[y] = sum(lx, y, rx, y);
            }
            // Now we need max over intervals [y1,y2] of (sum_{k=y1}^{y2} col[k]) / (dy)
            // where dy = ylist[y2] - ylist[y1]
            // This is like max average segment length problem, but denominator is difference in original y coordinates
            // Since ylist is sorted, we can use convex hull trick or brute force O(Y^2) if Y small
            // Y up to? Not specified, but typical constraints might allow O(N^2) overall? 
            // Let's do O(Y^2) per pair - worst-case if X~Y~sqrt(N) ~ 1000, then O(X^2 * Y^2) too large.
            // Instead, we can treat it as: for each top y2, we want max over y1<y2 of (prefix[y2+1]-prefix[y1]) / (ylist[y2]-ylist[y1])
            // That is max (prefix[y2+1] - prefix[y1]) / (ylist[y2] - ylist[y1])
            // Which is like maximum slope from points (ylist[y1], prefix[y1]) to (ylist[y2], prefix[y2+1])
            // So we can compute upper convex hull of points (ylist[y], pref[y]) and query for each y2.
            vector<ll> prefcol(Y+1, 0);
            for (int y = 0; y < Y; y++) {
                prefcol[y+1] = prefcol[y] + col[y];
            }
            // Points: (ylist[y], prefcol[y]) for y=0..Y
            // For each y2 from 1..Y, we want max (prefcol[y2] - prefcol[y1]) / (ylist[y2-1] - ylist[y1])? careful: interval [y1, y2-1] in compressed indices
            // Actually rectangle from y1 to y2 inclusive: sum = prefcol[y2+1] - prefcol[y1], dy = ylist[y2] - ylist[y1]
            // So we consider pairs (ylist[y], prefcol[y]) for y=0..Y
            // For each right point (ylist[y2], prefcol[y2+1]), we want max slope from left points (ylist[y1], prefcol[y1]) with y1<y2
            // Build convex hull of left points (x coordinate = ylist[y], y = prefcol[y])
            // The slope is (prefcol[y2+1] - prefcol[y1]) / (ylist[y2] - ylist[y1])
            // We'll maintain upper hull (for maximizing slope) of points seen so far.
            // Since x coordinates are increasing (ylist is sorted), we can use monotonic stack.
            struct Point {
                ll x, y;
            };
            auto cross = [](const Point& a, const Point& b, const Point& c) -> bool {
                // returns true if (b-a) x (c-b) <= 0 (clockwise or collinear, we want to remove b)
                return (b.y - a.y) * (c.x - b.x) <= (c.y - b.y) * (b.x - a.x);
            };
            vector<Point> hull;
            int ptr = 0;
            for (int y2 = 0; y2 <= Y; y2++) {
                // add left point (ylist[y2], prefcol[y2]) to hull
                Point p = {ylist[y2], prefcol[y2]};
                while (hull.size() >= 2 && cross(hull[hull.size()-2], hull.back(), p)) {
                    hull.pop_back();
                }
                hull.push_back(p);
                // now query for right point (ylist[y2], prefcol[y2+1])? Wait we need right point at y2-1? Actually for rectangle ending at y2 (inclusive), we need prefcol[y2+1] and ylist[y2].
                // For each y2 from 0 to Y-1 as top, we want right point (ylist[y2], prefcol[y2+1]).
                // But hull currently includes points up to y2 (inclusive) as left endpoints.
                // For top y2, left endpoints can be from 0 to y2, but we need y1 < y2 to have non-zero area, so left points up to y2-1.
                // So we should query before adding p? Actually we add p then query for next y2? Let's restructure.
            }
            // Simpler: for each y2 from 1 to Y (top index inclusive), we query hull built from points 0..y2-1.
            // So we can rebuild hull incrementally.
            hull.clear();
            for (int y2 = 0; y2 < Y; y2++) {
                // add point for y2 as possible left
                Point p = {ylist[y2], prefcol[y2]};
                while (hull.size() >= 2 && cross(hull[hull.size()-2], hull.back(), p)) {
                    hull.pop_back();
                }
                hull.push_back(p);
                // now query for top = y2 (so right point is (ylist[y2], prefcol[y2+1]))
                Point q = {ylist[y2], prefcol[y2+1]};
                // binary search for max slope
                int lo = 0, hi = (int)hull.size() - 1;
                while (lo < hi) {
                    int mid = (lo + hi) / 2;
                    // slope from hull[mid] to q vs hull[mid+1] to q
                    ll dy1 = q.y - hull[mid].y;
                    ll dx1 = q.x - hull[mid].x;
                    ll dy2 = q.y - hull[mid+1].y;
                    ll dx2 = q.x - hull[mid+1].x;
                    // compare dy1/dx1 < dy2/dx2
                    if (dy1 * dx2 < dy2 * dx1) {
                        lo = mid + 1;
                    } else {
                        hi = mid;
                    }
                }
                ll best_num = q.y - hull[lo].y;
                ll best_den = q.x - hull[lo].x;
                if (best_den > 0) {
                    Frac cur(best_num, best_den * dx);
                    if (best < cur) best = cur;
                }
            }
        }
    }

    cout << best.num << "/" << best.den << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Fraction {
    i128 num = -1; // numerator
    i128 den = 1;  // denominator
};

static inline i128 abs128(i128 x) { return x < 0 ? -x : x; }

static i128 gcd128(i128 a, i128 b) {
    a = abs128(a);
    b = abs128(b);
    while (b != 0) {
        i128 t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static bool better(i128 n1, i128 d1, i128 n2, i128 d2) {
    // compare n1/d1 > n2/d2
    return n1 * d2 > n2 * d1;
}

static string toString128(i128 x) {
    if (x == 0) return "0";
    bool neg = x < 0;
    if (neg) x = -x;
    string s;
    while (x > 0) {
        int digit = (int)(x % 10);
        s.push_back(char('0' + digit));
        x /= 10;
    }
    if (neg) s.push_back('-');
    reverse(s.begin(), s.end());
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int64> xs(n), ys(n), c(n);
    vector<int64> allx, ally;
    allx.reserve(n);
    ally.reserve(n);

    for (int i = 0; i < n; ++i) {
        cin >> xs[i] >> ys[i] >> c[i];
        allx.push_back(xs[i]);
        ally.push_back(ys[i]);
    }

    sort(allx.begin(), allx.end());
    allx.erase(unique(allx.begin(), allx.end()), allx.end());
    sort(ally.begin(), ally.end());
    ally.erase(unique(ally.begin(), ally.end()), ally.end());

    int X = (int)allx.size();
    int Y = (int)ally.size();

    vector<vector<int64>> grid(X + 1, vector<int64>(Y + 1, 0));

    for (int i = 0; i < n; ++i) {
        int xi = lower_bound(allx.begin(), allx.end(), xs[i]) - allx.begin() + 1;
        int yi = lower_bound(ally.begin(), ally.end(), ys[i]) - ally.begin() + 1;
        grid[xi][yi] += c[i];
    }

    // 2D prefix sums
    vector<vector<i128>> pref(X + 1, vector<i128>(Y + 1, 0));
    for (int i = 1; i <= X; ++i) {
        for (int j = 1; j <= Y; ++j) {
            pref[i][j] = pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1] + (i128)grid[i][j];
        }
    }

    auto rectSum = [&](int x1, int x2, int y1, int y2) -> i128 {
        // inclusive compressed indices, x1<=x2, y1<=y2
        return pref[x2][y2] - pref[x1 - 1][y2] - pref[x2][y1 - 1] + pref[x1 - 1][y1 - 1];
    };

    Fraction best;

    // Enumerate all pairs of x-columns and use all pairs of y-rows.
    // Rectangle borders pass through lattice points, and foxes on the border are included.
    for (int l = 1; l <= X; ++l) {
        for (int r = l + 1; r <= X; ++r) {
            i128 width = (i128)allx[r - 1] - (i128)allx[l - 1];
            if (width == 0) continue;

            // For each pair of y's
            for (int b = 1; b <= Y; ++b) {
                for (int t = b + 1; t <= Y; ++t) {
                    i128 height = (i128)ally[t - 1] - (i128)ally[b - 1];
                    if (height == 0) continue;

                    i128 cnt = rectSum(l, r, b, t);
                    i128 area = width * height;

                    if (best.num < 0 || better(cnt, area, best.num, best.den)) {
                        best.num = cnt;
                        best.den = area;
                    }
                }
            }
        }
    }

    // If no positive-area rectangle exists from given coordinates, answer is 0/1.
    // (Though problem guarantees rectangle with non-zero area should be considered.)
    if (best.num < 0) {
        cout << "0/1\n";
        return 0;
    }

    i128 g = gcd128(best.num, best.den);
    best.num /= g;
    best.den /= g;

    cout << toString128(best.num) << "/" << toString128(best.den) << "\n";
    return 0;
}
